function domesticateAndTame(horse: entity, p: offline player, i: int = 10):
	add {_i} to domestication level of {_horse}
	if domestication level of {_horse} >= max domestication level of {_horse}:
		tame {_horse}
		set tamer of {_horse} to {_p}

